package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.*;
import org.junit.*;

/** Original selected-tree reads only: exact byte windows, no decoder, writer or runtime. */
public final class ProjectHexReadTest {
    private Path root;private static final String CHECKOUT="11111111-1111-1111-1111-111111111111";
    @Before public void create()throws Exception{root=Files.createTempDirectory("pw-hex-read-");}
    @After public void close()throws Exception{try(var paths=Files.walk(root)){for(Path path:paths.sorted(java.util.Comparator.reverseOrder()).collect(java.util.stream.Collectors.toList()))Files.deleteIfExists(path);}}
    private JSONObject input(){try{return new JSONObject().put("path","data.bin").put("rangeMode","hex");}catch(Exception impossible){throw new AssertionError(impossible);}}
    private JSONObject read(JSONObject args)throws Exception{return ProjectFileQueries.read(root.toFile(),CHECKOUT,args,()->{});}
    @Test public void binaryWindowReturnsExactLowercaseBytesPrintableAsciiAndWholeFileHash()throws Exception{byte[] bytes={0,31,32,65,126,127,(byte)255,(byte)0xc3,(byte)0xa9};Files.write(root.resolve("data.bin"),bytes);JSONObject result=read(input());assertEquals("001f20417e7fffc3a9",result.getString("hex"));assertEquals(".. A~....",result.getString("ascii"));assertEquals(ProjectSources.sha256(bytes),result.getString("sha256"));assertEquals(0,result.getLong("byteOffset"));assertEquals(bytes.length,result.getInt("returnedBytes"));assertTrue(result.isNull("nextByteOffset"));assertTrue(result.getBoolean("complete"));assertFalse(result.has("content"));assertTrue(result.getBoolean("untrusted"));assertFalse(result.getBoolean("atomicReadFence"));assertArrayEquals(bytes,Files.readAllBytes(root.resolve("data.bin")));}
    @Test public void textByteOffsetsCanSplitUtf8WithoutPretendingTheWindowIsDecodedText()throws Exception{byte[] bytes="中文🙂".getBytes(StandardCharsets.UTF_8);Files.write(root.resolve("data.bin"),bytes);JSONObject result=read(input().put("offset",1).put("maxBytes",2));assertEquals("b8ad",result.getString("hex"));assertEquals("..",result.getString("ascii"));assertEquals(1,result.getLong("byteOffset"));assertEquals(3,result.getLong("nextByteOffset"));assertFalse(result.getBoolean("binary"));assertEquals("hex",result.getString("rangeMode"));assertFalse(result.has("returnedChars"));}
    @Test public void outputExpansionHasAnExplicitByteBudgetAndPagingMakesProgressWithoutLosingTail()throws Exception{byte[] bytes=new byte[5000];for(int i=0;i<bytes.length;i++)bytes[i]=(byte)i;Files.write(root.resolve("data.bin"),bytes);JSONObject first=read(input().put("maxBytes",8000));assertEquals(2048,first.getInt("maxWindowBytes"));assertEquals(2048,first.getInt("returnedBytes"));assertTrue(first.getBoolean("byteLimitApplied"));assertFalse(first.getBoolean("complete"));assertEquals(4096,first.getString("hex").length());assertEquals(2048,first.getString("ascii").length());assertTrue(first.toString().length()<11000);StringBuilder full=new StringBuilder();JSONObject page=first;while(true){full.append(page.getString("hex"));if(page.getBoolean("complete"))break;page=read(input().put("offset",page.getLong("nextByteOffset")).put("maxBytes",8000).put("expectedHash",first.getString("sha256")));}assertEquals(bytes.length*2,full.length());for(int i=0;i<bytes.length;i++)assertEquals(bytes[i]&255,Integer.parseInt(full.substring(2*i,2*i+2),16));}
    @Test public void emptyAndExactEofWindowsAreCompleteButBeyondEofAndInvalidNumericOrMixedTextRangesAreRefused()throws Exception{Files.write(root.resolve("data.bin"),new byte[0]);JSONObject empty=read(input());assertEquals("",empty.getString("hex"));assertEquals("",empty.getString("ascii"));assertEquals(0,empty.getInt("returnedBytes"));assertTrue(empty.getBoolean("complete"));assertTrue(empty.isNull("nextByteOffset"));Files.write(root.resolve("data.bin"),new byte[]{0,1});assertTrue(read(input().put("offset",2)).getBoolean("complete"));JSONObject beyond=read(input().put("offset",3));assertFalse(beyond.getBoolean("ok"));assertEquals("project_read_invalid_range",beyond.getString("code"));assertFalse(beyond.has("hex"));assertFalse(beyond.has("nextByteOffset"));for(Object offset:new Object[]{-1,0.5,"0",true})assertThrows(String.valueOf(offset),IllegalArgumentException.class,()->read(input().put("offset",offset)));for(Object limit:new Object[]{0,-1,1.5,"2",false})assertThrows(String.valueOf(limit),IllegalArgumentException.class,()->read(input().put("maxBytes",limit)));for(String text:new String[]{"maxChars","startLine","maxLines"})assertThrows(text,IllegalArgumentException.class,()->read(input().put(text,1)));assertThrows(IllegalArgumentException.class,()->read(input().put("metadataOnly",true)));}
    @Test public void expectedHashAndBeforeAfterShaFenceRefuseOldOrChangedWindows()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,1,2,3});String old=read(input()).getString("sha256");Files.write(root.resolve("data.bin"),new byte[]{0,4,5,6});assertThrows(SecurityException.class,()->read(input().put("expectedHash",old)));AtomicInteger checks=new AtomicInteger();assertThrows(SecurityException.class,()->ProjectFileQueries.read(root.toFile(),CHECKOUT,input(),()->{if(checks.incrementAndGet()==3)Files.write(root.resolve("data.bin"),new byte[]{0,9,8,7});}));assertArrayEquals(new byte[]{0,9,8,7},Files.readAllBytes(root.resolve("data.bin")));}
    @Test public void traversalLinksOversizeAndOriginalCancellationNeverYieldAHexBody()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,1});assertThrows(Exception.class,()->read(input().put("path","../outside.bin")));Files.createSymbolicLink(root.resolve("link.bin"),root.resolve("data.bin"));assertThrows(SecurityException.class,()->read(input().put("path","link.bin")));Files.write(root.resolve("large.bin"),new byte[ProjectSources.MAX_FILE_BYTES+1]);assertThrows(IllegalArgumentException.class,()->read(input().put("path","large.bin")));assertThrows(InterruptedException.class,()->ProjectFileQueries.read(root.toFile(),CHECKOUT,input(),()->{throw new InterruptedException("original cancelled");}));assertArrayEquals(new byte[]{0,1},Files.readAllBytes(root.resolve("data.bin")));}
    @Test public void defaultBinaryAndExistingTextReadModesAreUnchangedUntilHexIsExplicit()throws Exception{Files.write(root.resolve("data.bin"),new byte[]{0,(byte)255});JSONObject omitted=read(new JSONObject().put("path","data.bin"));assertTrue(omitted.getBoolean("contentOmitted"));assertEquals("binary_not_utf8_text",omitted.getString("reason"));assertFalse(omitted.has("hex"));Files.write(root.resolve("data.bin"),"hello\n中文".getBytes(StandardCharsets.UTF_8));assertEquals("hello",read(new JSONObject().put("path","data.bin").put("maxChars",5)).getString("content"));assertEquals("hello",read(new JSONObject().put("path","data.bin").put("rangeMode","bytes").put("maxBytes",5)).getString("content"));assertEquals("hello\n",read(new JSONObject().put("path","data.bin").put("rangeMode","lines").put("maxLines",1)).getString("content"));}
}
